WITH facts AS ( SELECT m.*, f.in_inbox,f.in_trash,f.in_junk,f.in_sent, -- Outlook drafts composed in Macro gain a provider id once synced; their shadow row keeps them Macro drafts. m.is_draft AND (m.provider_id IS NULL OR EXISTS ( SELECT 1 FROM email_mailbox_drafts d WHERE d.message_id = m.id AND NOT d.delete_requested )) AS macro_draft, EXISTS (SELECT 1 FROM email_message_recipients r WHERE r.message_id = m.id AND r.contact_id = m.from_contact_id) AS sender_is_recipient FROM email_messages m JOIN email_message_mailbox_facts f ON f.id = m.id WHERE m.thread_id = $1 AND m.link_id = $2 AND f.is_present ), aggregate AS ( SELECT COALESCE(bool_or(in_inbox AND NOT in_sent),false) AS mailbox_visible, COALESCE(bool_or(macro_draft),false) AS has_macro_draft, COALESCE(bool_or(in_inbox AND NOT in_trash AND NOT in_junk),false) AS has_inbox, COALESCE(bool_and(is_read),true) AS is_read, max(internal_date_ts) FILTER (WHERE in_inbox AND NOT is_draft AND (NOT is_sent OR sender_is_recipient)) AS received_ts, max(updated_at) FILTER (WHERE macro_draft) AS draft_ts, max(internal_date_ts) FILTER (WHERE is_sent AND NOT in_trash) AS outbound_ts, greatest(max(COALESCE(internal_date_ts, CASE WHEN is_draft THEN created_at END)) FILTER (WHERE NOT in_trash AND NOT in_junk),max(updated_at) FILTER (WHERE macro_draft AND NOT in_trash AND NOT in_junk)) AS all_ts FROM facts ), effective AS ( -- A Macro draft brings a thread back to the inbox only as a reply to received mail. SELECT a.*, a.mailbox_visible OR (t.has_received_mail AND a.has_macro_draft) OR (t.reminder_returned_at IS NOT NULL AND a.has_inbox) AS visible, greatest(a.received_ts, CASE WHEN t.has_received_mail THEN a.draft_ts END) AS inbound_ts FROM aggregate a JOIN email_threads t ON t.id = $1 AND t.link_id = $2 ) UPDATE email_threads t SET inbox_visible = a.visible,is_read = a.is_read, latest_inbound_message_ts = a.inbound_ts,latest_outbound_message_ts = a.outbound_ts, latest_non_spam_message_ts = a.all_ts,updated_at = now() FROM effective a WHERE t.id = $1 AND t.link_id = $2 AND (t.inbox_visible,t.is_read,t.latest_inbound_message_ts,t.latest_outbound_message_ts,t.latest_non_spam_message_ts) IS DISTINCT FROM (a.visible,a.is_read,a.inbound_ts,a.outbound_ts,a.all_ts)
